/* =========================================================
   RULES DATA
   Content for the entries inside the "Rules" dropdown in the
   Reference pane. Same {intro, entries:[{id, title, html,
   children?}]} shape as the other *-data.js files.

   Two entries are hand-written directly in index.html instead of
   living here, because they have live inputs/selects wired up in
   dm-screen.js rather than being plain data: Carrying & Encumbrance
   (id="dropCarryingEncumbrance") and Jumping (id="dropJumping").

   "Downtime Activities" nests every downtime-activity sub-page
   (Businesses, Buy a Magic Item, Carousing, etc.) as children, added
   incrementally as each one is ported from the source reference site.

   ORDER: the entries below are listed alphabetically by title, which
   is also the order they render in. dm-screen.js's renderRulesSection()
   slots the two hand-written calculators into their correct
   alphabetical positions by comparing each entry's title against the
   hand-written dropdowns' own <summary> text — so as long as this
   array stays alphabetically sorted, both calculators will always
   land in the right place without needing to be listed here at all.
   ========================================================= */

const RULES_DATA = {"intro": "", "entries": [
  {"id": "dropAbilityScoreModifiers", "title": "Ability Score Modifiers", "html": "<p>To determine an <a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-ability-score\">ability score</a> modifier, subtract 10 from the ability score and then divide the result by 2 (round down).</p><table class=\"humanoid-grid\"><thead><tr><th>Score</th><th>Modifier</th><th>Score</th><th>Modifier</th></tr></thead><tbody><tr><td>1</td><td>-5</td><td>16-17</td><td>+3</td></tr><tr><td>2-3</td><td>-4</td><td>18-19</td><td>+4</td></tr><tr><td>4-5</td><td>-3</td><td>20-21</td><td>+5</td></tr><tr><td>6-7</td><td>-2</td><td>22-23</td><td>+6</td></tr><tr><td>8-9</td><td>-1</td><td>24-25</td><td>+7</td></tr><tr><td>10-11</td><td>0</td><td>26-27</td><td>+8</td></tr><tr><td>12-13</td><td>+1</td><td>28-29</td><td>+9</td></tr><tr><td>14-15</td><td>+2</td><td>30</td><td>+10</td></tr></tbody></table>"},
  {"id": "dropCharacterAdvancement", "title": "Character Advancement, Experience & Leveling", "html": "<table class=\"humanoid-grid\"><thead><tr><th>Level</th><th><a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-experience-points\">Experience Points</a></th><th><a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-proficiency\">Proficiency</a> Bonus</th></tr></thead><tbody><tr><td>1</td><td>0</td><td>+2</td></tr><tr><td>2</td><td>300</td><td>+2</td></tr><tr><td>3</td><td>900</td><td>+2</td></tr><tr><td>4</td><td>2700</td><td>+2</td></tr><tr><td>5</td><td>6500</td><td>+3</td></tr><tr><td>6</td><td>14000</td><td>+3</td></tr><tr><td>7</td><td>23000</td><td>+3</td></tr><tr><td>8</td><td>34000</td><td>+3</td></tr><tr><td>9</td><td>48000</td><td>+4</td></tr><tr><td>10</td><td>64000</td><td>+4</td></tr><tr><td>11</td><td>85000</td><td>+4</td></tr><tr><td>12</td><td>100000</td><td>+4</td></tr><tr><td>13</td><td>120000</td><td>+5</td></tr><tr><td>14</td><td>140000</td><td>+5</td></tr><tr><td>15</td><td>165000</td><td>+5</td></tr><tr><td>16</td><td>195000</td><td>+5</td></tr><tr><td>17</td><td>225000</td><td>+6</td></tr><tr><td>18</td><td>265000</td><td>+6</td></tr><tr><td>19</td><td>305000</td><td>+6</td></tr><tr><td>20</td><td>355000</td><td>+6</td></tr></tbody></table>"},
  {"id": "dropCombat", "title": "Combat", "html": "<p>Combat is split into rounds and turns. A round represents about 6 seconds of in-game time. During a round, every combatant takes a turn: on your turn you can move up to your Speed and take one action (see below), and some classes and abilities also grant a single Bonus Action. Any combatant can also take one Reaction per round, which can trigger outside of your own turn.</p>\n<p>The table below covers what a character can do on their turn (or during the round). Class features, spells, and other abilities that grant extra actions (such as the Haste spell) aren't included here.</p>\n<h5>Movement</h5>\n<table class=\"humanoid-grid\"><thead><tr><th>Movement</th><th>Cost</th></tr></thead><tbody>\n<tr><td>Walk</td><td>Full movement</td></tr>\n<tr><td>Climb, Crawl</td><td>Every foot of movement crawling or climbing costs 1 extra foot</td></tr>\n<tr><td>Difficult Terrain</td><td>Every foot of movement in Difficult Terrain costs 1 extra foot</td></tr>\n<tr><td>Squeeze Through Small Spaces</td><td>Every foot of movement through small spaces costs 1 extra foot; Disadvantage on attack rolls and Dexterity saving throws while doing so</td></tr>\n<tr><td>Stand Up (from Prone)</td><td>Half your movement (e.g. 15 ft. of a 30 ft. Speed)</td></tr>\n</tbody></table>\n<h5>Interact with an Object (1 per round, free)</h5>\n<p>Once per round you can interact with one object for free, alongside your movement and action — for example: draw or sheathe a weapon, load a crossbow, hand an item to another creature, retrieve or stow an item in your pack, pick up or drop an item, move an object, open or close a door or chest, turn a key in a lock, pull a lever, don a mask, or extinguish a small flame.</p>\n<h5>Actions (1 per round, unless a feature grants more)</h5>\n<table class=\"humanoid-grid\"><thead><tr><th>Action</th><th>Effect</th></tr></thead><tbody>\n<tr><td>Attack</td><td>Make a melee or ranged attack</td></tr>\n<tr><td>Cast a Spell</td><td>With a casting time of 1 action</td></tr>\n<tr><td>Dash</td><td>Gain extra movement equal to your Speed</td></tr>\n<tr><td>Disengage</td><td>Your movement doesn't provoke opportunity attacks for the rest of the turn</td></tr>\n<tr><td>Dodge</td><td>Attack rolls against you have Disadvantage (if you can see the attacker); you make Dexterity saves with Advantage</td></tr>\n<tr><td>Escape a Grapple</td><td>Make a Strength (Athletics) or Dexterity (Acrobatics) check (your choice) contested by the grappler's Athletics</td></tr>\n<tr><td>Grapple</td><td>Target must be no more than one size larger than you and within your reach. Make a Strength (Athletics) check contested by the target's Athletics or Acrobatics (their choice)</td></tr>\n<tr><td>Help</td><td>An ally you assist gains Advantage on the next relevant ability check before the start of your next turn</td></tr>\n<tr><td>Hide</td><td>Make a Dexterity (Stealth) check to become hidden</td></tr>\n<tr><td>Improvise</td><td>Take an action not otherwise described here (break down a door, intimidate a foe, etc.)</td></tr>\n<tr><td>Ready</td><td>Choose a trigger and an action (or movement) to perform in response. If you ready a spell, you must maintain Concentration until it triggers</td></tr>\n<tr><td>Search</td><td>Make a Wisdom (Perception) or Intelligence (Investigation) check, depending on what you're looking for</td></tr>\n<tr><td>Stabilize</td><td>Use a healer's kit to stabilize a dying creature (no check required), or make a DC 10 Wisdom (Medicine) check without one</td></tr>\n<tr><td>Use an Object</td><td>Activate an item that requires an action to use</td></tr>\n</tbody></table>\n<h5>Bonus Actions (1 per round, only when a feature grants one)</h5>\n<table class=\"humanoid-grid\"><thead><tr><th>Bonus Action</th><th>Notes</th></tr></thead><tbody>\n<tr><td>Two-Weapon Fighting</td><td>Attack with your off-hand light weapon after attacking with a light melee weapon in your other hand</td></tr>\n<tr><td>Bonus Action Spells</td><td>Any spell whose casting time is listed as a bonus action — popular examples include Healing Word, Hex, Hunter's Mark, Misty Step, and Shield of Faith</td></tr>\n<tr><td>Rogue: Cunning Action</td><td>From level 2, a rogue can use a bonus action to Dash, Disengage, or Hide</td></tr>\n</tbody></table>\n<h5>Reactions (1 per round)</h5>\n<table class=\"humanoid-grid\"><thead><tr><th>Reaction</th><th>Trigger</th></tr></thead><tbody>\n<tr><td>Opportunity Attack</td><td>A hostile creature you can see leaves your reach (resolved before it finishes moving)</td></tr>\n<tr><td>Trigger a Readied Action</td><td>The circumstance you chose when you used the Ready action occurs</td></tr>\n<tr><td>Reactionary Spells</td><td>Any spell whose casting time is listed as a reaction — popular examples include Absorb Elements, Counterspell, Hellish Rebuke, and Shield</td></tr>\n</tbody></table>"},
  {"id": "dropContainerCapacity", "title": "Container Capacity", "html": "<table class=\"humanoid-grid\"><thead><tr><th>Container</th><th>Capacity</th><th>Cost</th><th>Weight</th></tr></thead><tbody>\n<tr><td>Backpack*</td><td>1 cubic foot / 30 lbs. of gear</td><td>2 gp</td><td>5 lb.</td></tr>\n<tr><td>Barrel</td><td>40 gallons liquid, 4 cubic feet solid</td><td>2 gp</td><td>70 lb.</td></tr>\n<tr><td>Basket</td><td>2 cubic feet / 40 lbs. of gear</td><td>4 sp</td><td>2 lb.</td></tr>\n<tr><td>Bottle</td><td>1½ pints of liquid</td><td>2 gp</td><td>2 lb.</td></tr>\n<tr><td>Bucket</td><td>3 gallons liquid, ½ cubic foot solid</td><td>5 cp</td><td>2 lb.</td></tr>\n<tr><td>Chest</td><td>12 cubic feet / 300 lbs. of gear</td><td>5 gp</td><td>25 lb.</td></tr>\n<tr><td>Flask or Tankard</td><td>1 pint of liquid</td><td>2 cp</td><td>1 lb.</td></tr>\n<tr><td>Jug or Pitcher</td><td>1 gallon of liquid</td><td>2 cp</td><td>4 lb.</td></tr>\n<tr><td>Pot, Iron</td><td>1 gallon of liquid</td><td>2 gp</td><td>10 lb.</td></tr>\n<tr><td>Pouch</td><td>1/5 cubic foot / 6 lbs. of gear</td><td>5 sp</td><td>1 lb.</td></tr>\n<tr><td>Sack</td><td>1 cubic foot / 30 lbs. of gear</td><td>1 cp</td><td>½ lb.</td></tr>\n<tr><td>Vial</td><td>4 ounces of liquid</td><td>1 gp</td><td>—</td></tr>\n<tr><td>Waterskin</td><td>4 pints of liquid</td><td>2 sp</td><td>5 lb.</td></tr>\n</tbody></table>\n<p>* You can also strap items, such as a bedroll or coil of rope, to the outside of a backpack.</p>"},
  {"id": "dropCover", "title": "Cover", "html": "<p><a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-half-cover\"><strong>Half Cover</strong></a> = +2 <a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-armor-class\">AC</a> and <a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-dexterity\">Dexterity</a> <a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-saving-throw\">Saving Throw</a></p><p><a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-three-quarters-cover\"><strong>Three-Quarters Cover</strong></a> = +5 <a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-armor-class\">AC</a> and <a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-dexterity\">Dexterity</a> <a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-saving-throw\">Saving Throw</a></p><p><a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-total-cover\"><strong>Total Cover</strong></a> = Can't be targeted directly</p>"},
  {"id": "dropCreatingTraps", "title": "Creating Traps", "html": "<p>When designing a trap, keep it proportionate to the party's level — an ill-suited trap can wipe out an entire group and end the adventure early. Use the table below as a guideline for damage, DC, and attack bonus by tier.</p>\n<table class=\"humanoid-grid\"><thead><tr><th>Character Level</th><th>Setback</th><th>Dangerous</th><th>Deadly</th></tr></thead><tbody>\n<tr><td>1st–4th</td><td>1d10 dmg, DC 10-11, +3 to +5</td><td>2d10 dmg, DC 12-15, +6 to +8</td><td>4d10 dmg, DC 16-20, +9 to +12</td></tr>\n<tr><td>5th–10th</td><td>2d10 dmg, DC 10-11, +3 to +5</td><td>4d10 dmg, DC 12-15, +6 to +8</td><td>10d10 dmg, DC 16-20, +9 to +12</td></tr>\n<tr><td>11th–16th</td><td>4d10 dmg, DC 10-11, +3 to +5</td><td>10d10 dmg, DC 12-15, +6 to +8</td><td>18d10 dmg, DC 16-20, +9 to +12</td></tr>\n<tr><td>17th–20th</td><td>10d10 dmg, DC 10-11, +3 to +5</td><td>18d10 dmg, DC 12-15, +6 to +8</td><td>24d10 dmg, DC 16-20, +9 to +12</td></tr>\n</tbody></table>\n<h5>Trap Damage Examples</h5>\n<p>A few examples of trap effects, including low-level spells that can be reflavored as trap triggers (a gas trap might work like Cloudkill; a sprung Darkness spell could blind everyone nearby). A DM can adapt many other spells the same way.</p>\n<table class=\"humanoid-grid\"><thead><tr><th>Trap</th><th>Damage</th><th>Notes</th></tr></thead><tbody>\n<tr><td>Stinking Cloud (spell)</td><td>—</td><td>Constitution save or spend your turns retching and reeling, for 1 minute unless dispersed</td></tr>\n<tr><td>Darkness (spell)</td><td>—</td><td>Blinds the party in the affected area</td></tr>\n<tr><td>Silence (spell)</td><td>—</td><td>Creates an area where spells can't be cast</td></tr>\n<tr><td>Globe of Invulnerability (spell)</td><td>—</td><td>Traps a creature for 1 minute — perhaps while enemies are alerted, or the floor slowly reveals a pit below</td></tr>\n<tr><td>Falling</td><td>1d6 per 10 ft. (max 20d6)</td><td>Possible Dexterity (Acrobatics) check for short falls; the creature lands Prone</td></tr>\n<tr><td>Frostbite (spell)</td><td>1d6</td><td>Constitution save or take cold damage</td></tr>\n<tr><td>Earth Tremor (spell)</td><td>1d6</td><td>Dexterity save or take bludgeoning damage</td></tr>\n<tr><td>Ray of Frost (spell)</td><td>1d8</td><td>More damage at higher levels: 2d10 (5th), 3d10 (11th), 4d10 (17th)</td></tr>\n<tr><td>Falling Bookcase</td><td>1d10</td><td></td></tr>\n<tr><td>Firebolt (spell)</td><td>1d10</td><td>More damage at higher levels: 2d10 (5th), 3d10 (11th), 4d10 (17th)</td></tr>\n<tr><td>Eldritch Blast (spell)</td><td>1d10</td><td>More damage at higher levels: 2d10 (5th), 3d10 (11th), 4d10 (17th)</td></tr>\n<tr><td>Lightning Bolt</td><td>2d10</td><td>Lightning damage</td></tr>\n<tr><td>Fire Pit</td><td>2d10</td><td></td></tr>\n<tr><td>Collapsing Tunnel</td><td>4d10</td><td></td></tr>\n<tr><td>Vat of Acid</td><td>4d10</td><td></td></tr>\n<tr><td>Cloudkill (spell)</td><td>5d8</td><td>Poison damage, Constitution save for half</td></tr>\n<tr><td>Whirling Steel Blades</td><td>10d10</td><td></td></tr>\n<tr><td>Strong Lava Spray</td><td>10d10</td><td></td></tr>\n<tr><td>Pit of Lava (submerged)</td><td>18d10</td><td></td></tr>\n<tr><td>Vortex of Fire (submerged)</td><td>24d10</td><td></td></tr>\n</tbody></table>\n<h5>Random Trap</h5>\n<p>A quick table of trap effects (the trigger is up to the DM). Cross-reference the Damage Severity table above, by party level, to keep the actual damage proportionate.</p>\n<table class=\"humanoid-grid\"><thead><tr><th>d100</th><th>Effect</th></tr></thead><tbody>\n<tr><td>1-4</td><td>Magic missiles shoot from a statue, object, or wall</td></tr>\n<tr><td>5-7</td><td>Collapsing staircase becomes a ramp, depositing characters into a pit at the bottom</td></tr>\n<tr><td>8-10</td><td>A stone block falls from the ceiling</td></tr>\n<tr><td>11-12</td><td>The room locks and the ceiling slowly lowers</td></tr>\n<tr><td>13-14</td><td>A chute opens in the floor</td></tr>\n<tr><td>15-16</td><td>A clanging noise attracts nearby monsters</td></tr>\n<tr><td>17-19</td><td>Touching an object triggers a Disintegrate spell</td></tr>\n<tr><td>20-23</td><td>A door or object is coated with contact poison</td></tr>\n<tr><td>24-27</td><td>Fire shoots from a wall, floor, or object</td></tr>\n<tr><td>28-30</td><td>Touching an object triggers a Flesh to Stone spell</td></tr>\n<tr><td>31-33</td><td>The floor collapses, or is an illusion</td></tr>\n<tr><td>34-36</td><td>A vent releases gas — blinding, acidic, obscuring, paralyzing, poisonous, or sleep-inducing</td></tr>\n<tr><td>37-39</td><td>Floor tiles are electrified</td></tr>\n<tr><td>40-43</td><td>A Glyph of Warding triggers</td></tr>\n<tr><td>44-46</td><td>A huge wheeled statue rolls down the corridor</td></tr>\n<tr><td>47-49</td><td>A lightning bolt shoots from a wall or object</td></tr>\n<tr><td>50-52</td><td>A locked room floods with water or acid</td></tr>\n<tr><td>53-56</td><td>Darts shoot out of an opened chest</td></tr>\n<tr><td>57-59</td><td>A weapon, suit of armor, or rug animates and attacks when touched (see Animated Object in the Monster Manual)</td></tr>\n<tr><td>60-62</td><td>A pendulum (bladed or a weighted maul) swings across the room or hall</td></tr>\n<tr><td>63-67</td><td>A hidden pit opens underfoot (25% chance a black pudding or gelatinous cube fills the bottom)</td></tr>\n<tr><td>68-70</td><td>A hidden pit floods with acid or fire</td></tr>\n<tr><td>71-73</td><td>A pit opens and swallows the target, then quickly locks shut and floods with water</td></tr>\n<tr><td>74-77</td><td>A scything blade emerges from a wall or object</td></tr>\n<tr><td>78-81</td><td>Spears (possibly poisoned) spring out</td></tr>\n<tr><td>82-84</td><td>Brittle stairs collapse over spikes</td></tr>\n<tr><td>85-88</td><td>A Thunderwave effect knocks characters into a pit or spikes</td></tr>\n<tr><td>89-91</td><td>Steel or stone jaws restrain a character</td></tr>\n<tr><td>92-94</td><td>A stone block smashes across the hallway</td></tr>\n<tr><td>95-97</td><td>A Symbol spell triggers</td></tr>\n<tr><td>98-100</td><td>The walls slide together</td></tr>\n</tbody></table>"},
  {"id": "dropCreatureTypes", "title": "Creature Types by Skill", "html": "<p><strong class=\"skill-label-large\"><a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-arcana\">Arcana</a>:</strong> <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"creature-type-aberration\">Aberration</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"creature-type-construct\">Construct</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"creature-type-elemental\">Elemental</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"creature-type-fey\">Fey</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"creature-type-monstrosity\">Monstrosity</a></p><p><strong class=\"skill-label-large\"><a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-history\">History</a> / <a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-medicine\">Medicine</a>:</strong> <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"creature-type-giant\">Giant</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"creature-type-humanoid\">Humanoid</a></p><p><strong class=\"skill-label-large\"><a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-nature\">Nature</a>:</strong> <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"creature-type-beast\">Beast</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"creature-type-dragon\">Dragon</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"creature-type-ooze\">Ooze</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"creature-type-plant\">Plant</a></p><p><strong class=\"skill-label-large\"><a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-religion\">Religion</a>:</strong> <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"creature-type-celestial\">Celestial</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"creature-type-fiend\">Fiend</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"creature-type-undead\">Undead</a></p>"},
  {"id": "rules-downtime-activities", "title": "Downtime Activities", "html": "", "children": [{"id": "rules-businesses", "title": "Businesses", "html": "", "children": [{"id": "rules-business-downtime-profits", "title": "Downtime Business Profits (Official)", "html": "<p>The DMG greatly simplifies running a business. During a player's downtime, they can choose to spend some time running a business that they own. According to the DMG p129, \"a character rolls percentile dice and adds the number of days spent on [his/her] downtime activity (maximum 30), then compares the total to the Running a Business table\" (see below). The DMG ignores inventory costs, repairs, and other such expenses, as income is believed to offset those costs. The cost of staff is the only real cost that the DMG uses for maintenance (although DMs are free to add other costs, such as taxes from a ruthless ruler). Whether a player has to pay those maintenance costs is dependent on their roll.</p><table class=\"humanoid-grid\"><thead><tr><th>d100 + Days</th><th>Result</th></tr></thead><tbody><tr><td>01-20</td><td>You must pay one and a half times the business's maintenance cost for each of the days</td></tr><tr><td>21-30</td><td>You must pay the business's full maintenance cost for each of the days</td></tr><tr><td>31-40</td><td>You must pay half the business's maintenance cost for each of the days</td></tr><tr><td>41-60</td><td>The business covers its own maintenance cost for each of the days</td></tr><tr><td>61-80</td><td>The business covers its own maintenance cost for each of the days, plus a profit of 1d6 x 5gp</td></tr><tr><td>81-90</td><td>The business covers its own maintenance cost for each of the days, plus a profit of 2d8 x 5gp</td></tr><tr><td>91+</td><td>The business covers its own maintenance cost for each of the days, plus a profit of 3d10 x 5gp</td></tr></tbody></table>"}, {"id": "rules-business-alternative-profits", "title": "Alternative Business Profits (Optional)", "html": "<p>Since D&amp;D is about adventuring, getting \"free gold\" from a business does not always work well in a game system where players look for treasure and loot. It is also added work for the DM to manage and track. However, some DMs may wish to add a little more realism — while a party is adventuring, it is possible for a business to thrive and become a lucrative enterprise. Alternatively, a business can be raided by bandits, fall prey to arson, be infested by rats, or just have very little customers. Every business cycle (up to the DM: month, week, quarter, year), the DM can roll on the following table.</p><p>In order to use the table below, the DM must know the maintenance costs (which is typically the staff salaries) and the value of the business (this is usually the price paid for the business). The DM can choose to roll for a straight profit/loss (usually 5gp-150gp), or they can base the profit/loss on the business value (last column).</p><p>Note: Profit/loss based on the business value uses a percentage of the value of a business — which means that a large, luxurious tavern that cost 50,000gp will potentially earn much more than a seedy tavern in a bad neighborhood that cost 6,000gp. This may lead to very high profits, but also very large losses (DMs should be cautious).</p><table class=\"humanoid-grid\"><thead><tr><th>d100</th><th>Occurrence</th><th>Change in Value</th><th>Profit/Loss</th><th>Profit/Loss by Value</th></tr></thead><tbody><tr><td>01</td><td>The business burned to the ground, leaving nothing but ashes</td><td>-100%</td><td>Business lost.</td><td>Business lost.</td></tr><tr><td>02</td><td>The business was seized by the local ruler, claiming criminal activity</td><td>-100%</td><td>Business lost. You may be able to speak to the ruler, or pay a high fine (50% of value).</td><td>Business lost. You may be able to speak to the ruler, or pay a high fine (50% of value).</td></tr><tr><td>03</td><td>A fire has destroyed part of the business, and must be repaired</td><td>-10%</td><td>Loss: maint. cost x 2</td><td>Loss: 10% of value + 5d10x5gp</td></tr><tr><td>04-05</td><td>The market crashes, inventory is hard to find and customers are scarce</td><td>-5%</td><td>Loss: maint. cost x 1.5</td><td>Loss: 5% of value + 5d10x5gp</td></tr><tr><td>06-10</td><td>Bandits &amp; thieves rob the business, leaving little behind.</td><td>0%</td><td>Loss: maint. cost x 1.5</td><td>Loss: 2% of value + 3d10x5gp</td></tr><tr><td>11-15</td><td>The business was infested with vermin, ruining inventory and scaring off customers.</td><td>0%</td><td>Loss: maint. cost x 1.5</td><td>Loss: 1% of value + 2d10x5gp</td></tr><tr><td>16-17</td><td>A noble or local leader has a vendetta against you and is making business difficult.</td><td>0%</td><td>Loss: maint. cost x 1.5</td><td>Loss: 1% of value + 2d10x5gp</td></tr><tr><td>18-19</td><td>The local ruler added sharp fees and taxes this last business cycle.</td><td>0%</td><td>Loss: maint. cost x 1.5</td><td>Loss: 1% of value + 2d10x5gp</td></tr><tr><td>20-21</td><td>Supply shortages have increased wholesale prices, increasing costs.</td><td>0%</td><td>Loss: maint. costs</td><td>Loss: 1% of value + 2d10x5gp</td></tr><tr><td>22-23</td><td>A storm caused damage to the structure and had to be repaired</td><td>0%</td><td>Loss: maint. costs</td><td>Loss: 0.5% of value + 1d8x5gp</td></tr><tr><td>24-25</td><td>A local crime lord sent thugs to your business to collect protection money.</td><td>0%</td><td>Loss: maint. costs</td><td>Loss: 0.5% of value + 1d8x5gp</td></tr><tr><td>26-27</td><td>An employee robbed the store and never returned.</td><td>0%</td><td>Loss: maint. costs</td><td>Loss: 0.5% of value + 1d8x5gp</td></tr><tr><td>28-30</td><td>Bloody cultist symbols were painted on the structure, scaring customers</td><td>0%</td><td>Loss: maint. costs</td><td>Loss: 0.5% of value + 1d8x5gp</td></tr><tr><td>31-32</td><td>The local ruler temporarily mistakenly closed the business for a few days.</td><td>0%</td><td>Loss: ½ maint. costs</td><td>Loss: 0.2% of value + 1d6x5gp</td></tr><tr><td>33-34</td><td>You lost a key vendor and had to find supplies elsewhere, this slowed business.</td><td>0%</td><td>Loss: ½ maint. costs</td><td>Loss: 0.2% of value + 1d6x5gp</td></tr><tr><td>35-36</td><td>The neighborhood has taken a turn for the worse, leading to poorer clientele.</td><td>0%</td><td>Loss: ½ maint. costs</td><td>Loss: 0.2% of value + 1d6x5gp</td></tr><tr><td>37-38</td><td>Crime has risen in the neighborhood, leading to fewer customers.</td><td>0%</td><td>Loss: ½ maint. costs</td><td>Loss: 0.1% of value + 1d6x5gp</td></tr><tr><td>39-40</td><td>A competitor has been spreading wicked rumors about the business.</td><td>0%</td><td>Loss: ½ maint. costs</td><td>Loss: 0.1% of value + 1d6x5gp</td></tr><tr><td>41-60</td><td>The business breaks even this period.</td><td>0%</td><td>—</td><td>—</td></tr><tr><td>61-62</td><td>Word is spreading about the business, and business is up this period.</td><td>0%</td><td>Gain: 1d6x5gp</td><td>Gain: 0.1% of value + 1d6x5gp</td></tr><tr><td>63-64</td><td>A higher class of citizens have moved into the area, increasing business.</td><td>0%</td><td>Gain: 1d6x5gp</td><td>Gain: 0.1% of value + 1d6x5gp</td></tr><tr><td>65-66</td><td>Crime has decreased in the area, and patrols have increased, increasing business.</td><td>0%</td><td>Gain: 1d6x5gp</td><td>Gain: 0.2% of value + 1d6x5gp</td></tr><tr><td>67-68</td><td>A local trade guild has made your business a preferred associate this period.</td><td>0%</td><td>Gain: 1d6x5gp</td><td>Gain: 0.2% of value + 1d6x5gp</td></tr><tr><td>69-70</td><td>You managed to buy supplies at a discount this period.</td><td>0%</td><td>Gain: 1d6x5gp</td><td>Gain: 0.2% of value + 1d6x5gp</td></tr><tr><td>71-72</td><td>Your employees were energetic and hard working this period.</td><td>0%</td><td>Gain: 1d6x5gp</td><td>Gain: 0.2% of value + 1d6x5gp</td></tr><tr><td>73-74</td><td>Your business was written up in a local paper, increasing business.</td><td>0%</td><td>Gain: 1d6x5gp</td><td>Gain: 0.5% of value + 1d8x5gp</td></tr><tr><td>75-76</td><td>Town criers have been raving about the high quality of your business.</td><td>0%</td><td>Gain: 1d6x5gp</td><td>Gain: 0.5% of value + 1d8x5gp</td></tr><tr><td>77-78</td><td>A local noble visited your business and made a large purchase this period.</td><td>0%</td><td>Gain: 1d6x5gp</td><td>Gain: 0.5% of value + 1d8x5gp</td></tr><tr><td>79-80</td><td>A local festival brought in plenty of customers this period.</td><td>0%</td><td>Gain: 1d6x5gp</td><td>Gain: 0.5% of value + 1d8x5gp</td></tr><tr><td>81-82</td><td>The neighborhood appears to have grown, and so have profits this period.</td><td>0%</td><td>Gain: 2d8x5gp</td><td>Gain: 1% of value + 2d10x5gp</td></tr><tr><td>83-84</td><td>The market is soaring in the region and business is good.</td><td>0%</td><td>Gain: 2d8x5gp</td><td>Gain: 1% of value + 2d10x5gp</td></tr><tr><td>85-86</td><td>A wealthy patron stopped in and spent quite a great deal of coin this period.</td><td>0%</td><td>Gain: 2d8x5gp</td><td>Gain: 1% of value + 2d10x5gp</td></tr><tr><td>87-91</td><td>High demand for your products/services led to high profits this period.</td><td>0%</td><td>Gain: 2d8x5gp</td><td>Gain: 1% of value + 2d10x5gp</td></tr><tr><td>92-94</td><td>Your product/service is talked about in far off kingdoms this period.</td><td>0%</td><td>Gain: 2d8x5gp</td><td>Gain: 2% of value + 3d10x5gp</td></tr><tr><td>95-96</td><td>A high noble and his retinue nearly bought out your entire inventory this period.</td><td>0%</td><td>Gain: 3d10x5gp</td><td>Gain: 2% of value + 5d10x5gp</td></tr><tr><td>97</td><td>The business is blessed with good fortune this period.</td><td>0%</td><td>Gain: 3d10x5gp</td><td>Gain: 2% of value + 5d10x5gp</td></tr><tr><td>99</td><td>Your business was mentioned at court, and business soars this period.</td><td>+5%</td><td>Gain: 4d12x5gp</td><td>Gain: 5% of value + 5d10x5gp</td></tr><tr><td>00</td><td>The holy ones divine that your business is blessed by the god(s).</td><td>+10%</td><td>Gain: 3d20x5gp</td><td>Gain: 10% of value + 5d10x5gp</td></tr></tbody></table><p>Note: A creative DM can take any of the \"loss\" situations and use them as an adventure hook. For example, \"Bloody cultist symbols were painted on the structure, scaring customers\" could make the party seek out these cultists. Or, \"A fire has destroyed part of the business, and must be repaired\" could lead the party to some evidence of arson, and the party will need to find the culprits.</p><h5>Modifiers to d100</h5><table class=\"humanoid-grid\"><thead><tr><th>Condition</th><th>Modifier</th></tr></thead><tbody><tr><td>Have an Experienced Manager or Clerk (12gp/month)</td><td>+1 (max +1)</td></tr><tr><td>While Adventuring, Actively Promoted the Business to Others (i.e. \"Persuaded\" traders to visit the business)</td><td>+1 (max +5)</td></tr><tr><td>While Adventuring, Poorly Promoted the Business (i.e. own a tavern but lost a drinking contest)</td><td>-1 (max -5)</td></tr></tbody></table><h5>Last Period Expenses and Events</h5><table class=\"humanoid-grid\"><thead><tr><th>Condition</th><th>Modifier</th></tr></thead><tbody><tr><td>Gold spent on Marketing &amp; Promotions (last period)</td><td>+1 / 5gp spent (max +10)</td></tr><tr><td>Gold spent on Repairs &amp; Improvements (last period)</td><td>+1 / 10gp spent (max +5)</td></tr><tr><td>There was a Festival, Carnival or Tournament (last period)</td><td>+1 (max +1)</td></tr></tbody></table>"}]}]},
  {"id": "dropFoodWaterNeeds", "title": "Food & Water Needs", "html": "<h5>Food</h5>\n<p>A character needs one pound of food per day, and can subsist on half rations — eating half a pound in a day counts as half a day without food. A character can go without food for a number of days equal to 3 + their Constitution modifier (minimum 1); at the end of each day beyond that, they automatically suffer one level of Exhaustion. A normal day of eating resets the count back to zero.</p>\n<h5>Water</h5>\n<p>A character needs one gallon of water per day (two waterskins' worth), doubled in hot weather. A character who drinks only half that must succeed on a DC 15 Constitution saving throw or suffer one level of Exhaustion at the end of the day; a character with access to even less water automatically suffers one level of Exhaustion. If they already have one or more levels of Exhaustion, they take two levels instead.</p>\n<table class=\"humanoid-grid\"><thead><tr><th>Creature Size</th><th>Food per Day</th></tr></thead><tbody>\n<tr><td>Tiny</td><td>¼ pound</td></tr>\n<tr><td>Small</td><td>1 pound*</td></tr>\n<tr><td>Medium</td><td>1 pound*</td></tr>\n<tr><td>Large</td><td>4 pounds</td></tr>\n<tr><td>Huge</td><td>16 pounds</td></tr>\n<tr><td>Gargantuan</td><td>64 pounds</td></tr>\n</tbody></table>\n<p>* A day's ration weighs 2 lb., but a character only needs 1 lb. of food per day to avoid the effects of starvation — a ration is sized for comfort, not the bare survival minimum.</p>\n<h5>Optional Rule: Going Hungry</h5>\n<p>If a character survives on the bare minimum of 1 lb. of food per day, after 3 days they suffer a -2 penalty to Perception checks and their Speed is reduced by 5 feet, until they eat a full ration again. (Since Exhaustion is already the penalty for not even meeting the minimum, this optional penalty for meeting only the minimum stays lighter than that.)</p>"},
  {"id": "dropImprovisedDamage", "title": "Improvised Damage", "html": "<p>Improvised damage is a way to work out how much damage a nonstandard attack or hazard should deal — anything that clearly deals damage but doesn't already have a set amount in the rules.</p>\n<h5>Improvised Damage Examples</h5>\n<table class=\"humanoid-grid\"><thead><tr><th>Dice</th><th>Examples</th></tr></thead><tbody>\n<tr><td>1d10</td><td>Burned by coals, hit by a falling bookcase, pricked by a poisoned needle</td></tr>\n<tr><td>2d10</td><td>Struck by lightning, stumbling into a fire pit</td></tr>\n<tr><td>4d10</td><td>Hit by falling rubble in a collapsing tunnel, stumbling into a vat of acid</td></tr>\n<tr><td>10d10</td><td>Crushed by compacting walls, hit by whirling steel blades, wading through a lava stream</td></tr>\n<tr><td>18d10</td><td>Submerged in lava, hit by a crashing flying fortress</td></tr>\n<tr><td>24d10</td><td>Tumbling into a vortex of fire on the Elemental Plane of Fire, crushed in the jaws of a godlike or moon-sized creature</td></tr>\n</tbody></table>\n<h5>Damage Severity by Level</h5>\n<p>A DM should be careful not to deal excessive improvised damage to a low-level party. The table below is a guideline for how deadly improvised damage can be at each tier.</p>\n<table class=\"humanoid-grid\"><thead><tr><th>Level</th><th>Setback</th><th>Dangerous</th><th>Deadly</th></tr></thead><tbody>\n<tr><td>1st–4th</td><td>1d10</td><td>2d10</td><td>4d10</td></tr>\n<tr><td>5th–10th</td><td>2d10</td><td>4d10</td><td>10d10</td></tr>\n<tr><td>11th–16th</td><td>4d10</td><td>10d10</td><td>18d10</td></tr>\n<tr><td>17th–20th</td><td>10d10</td><td>18d10</td><td>24d10</td></tr>\n</tbody></table>"},
  {"id": "dropLanguages", "title": "Languages", "html": "<h5>Common Languages</h5>\n<table class=\"humanoid-grid\"><thead><tr><th>Language</th><th>Typical Speakers</th><th>Script</th></tr></thead><tbody>\n<tr><td>Common</td><td>Humans</td><td>Common</td></tr>\n<tr><td>Dwarvish</td><td>Dwarves</td><td>Dwarvish</td></tr>\n<tr><td>Elvish</td><td>Elves</td><td>Elvish</td></tr>\n<tr><td>Giant</td><td>Ogres, giants</td><td>Dwarvish</td></tr>\n<tr><td>Gnomish</td><td>Gnomes</td><td>Dwarvish</td></tr>\n<tr><td>Goblin</td><td>Goblinoids</td><td>Dwarvish</td></tr>\n<tr><td>Halfling</td><td>Halflings</td><td>Common</td></tr>\n<tr><td>Orc</td><td>Orcs</td><td>Dwarvish</td></tr>\n</tbody></table>\n<h5>Exotic Languages</h5>\n<table class=\"humanoid-grid\"><thead><tr><th>Language</th><th>Typical Speakers</th><th>Script</th></tr></thead><tbody>\n<tr><td>Abyssal</td><td>Demons</td><td>Infernal</td></tr>\n<tr><td>Celestial</td><td>Celestials</td><td>Celestial</td></tr>\n<tr><td>Deep Speech</td><td>Mind flayers, beholders</td><td>—</td></tr>\n<tr><td>Draconic</td><td>Dragons, dragonborn</td><td>Draconic</td></tr>\n<tr><td>Infernal</td><td>Devils</td><td>Infernal</td></tr>\n<tr><td>Primordial</td><td>Elementals</td><td>Dwarvish</td></tr>\n<tr><td>Sylvan</td><td>Fey creatures</td><td>Elvish</td></tr>\n<tr><td>Undercommon</td><td>Underdark traders</td><td>Elvish</td></tr>\n</tbody></table>"},
  {"id": "dropLifestyleCosts", "title": "Lifestyle Costs", "html": "<p>Whether living in squalor or in luxury, it costs money. The table below outlines living costs for each lifestyle.</p>\n<table class=\"humanoid-grid\"><thead><tr><th>Lifestyle</th><th>Cost/Day</th><th>Cost/Week</th><th>Cost/Month</th></tr></thead><tbody>\n<tr><td>Wretched</td><td>—</td><td>—</td><td>—</td></tr>\n<tr><td>Squalid</td><td>1 sp</td><td>7 sp</td><td>3 gp</td></tr>\n<tr><td>Poor</td><td>2 sp</td><td>14 sp</td><td>6 gp</td></tr>\n<tr><td>Modest</td><td>1 gp</td><td>7 gp</td><td>28 gp</td></tr>\n<tr><td>Comfortable</td><td>2 gp</td><td>14 gp</td><td>56 gp</td></tr>\n<tr><td>Wealthy</td><td>4 gp</td><td>28 gp</td><td>112 gp</td></tr>\n<tr><td>Aristocratic</td><td>10 gp minimum</td><td>70 gp minimum</td><td>280 gp minimum</td></tr>\n</tbody></table>"},
  {"id": "dropMountedCombat", "title": "Mounted Combat", "html": "<p>A mount can be any willing creature at least one size larger than its rider, with anatomy suited to riding. Small creatures (halflings, gnomes, goblins, kobolds) can ride Medium mounts such as mules, wolves, goats, giant frogs, or dolphins. A mount can be controlled only if it's been trained to accept a rider, or if it's an intelligent creature (typically Intelligence 6 or higher, though it's ultimately the DM's call).</p>\n<h5>Mounting/Dismounting</h5>\n<p>Mounting or dismounting costs half your movement Speed, and isn't an action — but you can't do it at all if your Speed is 0. The mount must be within 5 feet of you, regardless of either creature's size or reach.</p>\n<h5>Forced Dismounting</h5>\n<p>If an effect moves your mount against its will while you're on it, you must succeed on a DC 10 Dexterity saving throw or fall off, landing Prone in a space within 5 feet of the mount's new location. The check is still required even if the effect moves both of you together.</p>\n<p>If you're knocked Prone while mounted (or grappled and moved, shoved, etc.), you make the same saving throw — you may be unseated without it affecting your mount. On a failure you fall off Prone within 5 feet of the mount; on a success you stay in the saddle.</p>\n<p>If your mount is knocked Prone, you can use your Reaction to dismount as it falls and land on your feet; otherwise you're dismounted and land Prone within 5 feet of it.</p>\n<p>A military saddle gives Advantage on checks made to stay mounted (not on saving throws).</p>\n<h5>Controlling Mounts</h5>\n<p>You can either control a mount or let it act independently. Intelligent creatures (such as dragons) act independently with no restriction on their actions. You can control a mount only if it's been trained to accept a rider.</p>\n<h5>Controlled Mounts</h5>\n<p>A controlled mount's Initiative changes to match yours when you mount it. It moves as you direct and has only three action options — Dash, Disengage, and Dodge — though it can still use any Bonus Actions and Reactions it has, and can move and act on the very turn you mount it. If you have the Mounted Combatant feat, you have Advantage on melee attack rolls against any unmounted creature smaller than your mount while controlling it.</p>\n<h5>Opportunity Attacks</h5>\n<p>If your mount provokes an opportunity attack while you're on it, the attacker can target either you or the mount. A mount only has three actions available (Dash, Disengage, Dodge) but has no restriction on its Reaction — so as long as it has a Reaction available, it can reasonably take an opportunity attack of its own, though there's no explicit rule for this and it's ultimately a DM call.</p>\n<h5>Where Are You While Mounted? (Reach)</h5>\n<p>This is a genuinely debated topic with no single official answer; three common house-rule approaches, each with tradeoffs, are:</p>\n<p><strong>Mearls Method:</strong> the rider is a free-moving creature effectively trapped inside a box the shape of the mount's space, and must spend movement to climb around the mount to reach different targets. More realistic, but requires the DM to track a \"facing\" for the mount, and complicates both lance rules and the Mounted Combatant feat's second benefit.</p>\n<p><strong>Blob Method:</strong> mounting a creature merges the rider and mount into a single shared space. Simple to run, but unrealistic at large scale (e.g. a rider on a huge creature could threaten any square adjacent to it).</p>\n<p><strong>Center of Mass Method:</strong> the rider occupies the center-most square(s) of the mount's space — the mount's entire space on a same-size mount, just the center square on a larger one. Realistic and keeps reach/ranged weapons sensible, but still complicates the Mounted Combatant feat's second benefit if the rider ends up out of the attacker's reach.</p>\n<h5>Feats and Mounts</h5>\n<p><strong>Charger</strong> requires you to use your own action (not your mount's) to Dash, so it doesn't function while mounted.</p>\n<p><strong>Defensive Duelist</strong> lets you use your Reaction to boost your AC while wielding a finesse weapon you're proficient with — useful alongside Mounted Combatant, since you can use it against attacks redirected from your mount. It does not raise your mount's own AC.</p>\n<p><strong>Mounted Combatant</strong> has three benefits: Advantage on melee attacks against unmounted creatures smaller than your mount; the ability to force an attack against your mount to target you instead (most useful under the Blob Method, above); and your mount takes no damage on a successful Dexterity save that would normally halve damage, and half damage on a failure.</p>"},
  {"id": "dropObjectsDoorsWalls", "title": "Objects, Doors & Walls", "html": "<p>Given enough time and the right tools, a party can eventually break most objects — but a DM should use judgment (a sword shouldn't cut through a stone wall, and a loud attempt to chop down a door might wake nearby enemies or attract a patrol). When time is a factor, assign the object an Armor Class and Hit Points, and optionally immunities, resistances, or vulnerabilities to specific damage types.</p>\n<p>For these rules, an \"object\" is a single, discrete, inanimate item — a window, door, sword, book, table, chair, or stone — not a whole building or vehicle made up of many objects.</p>\n<h5>Object Armor Class</h5>\n<table class=\"humanoid-grid\"><thead><tr><th>Substance</th><th>AC</th></tr></thead><tbody>\n<tr><td>Cloth, paper, rope</td><td>11</td></tr>\n<tr><td>Crystal, glass, ice</td><td>13</td></tr>\n<tr><td>Wood, bone</td><td>15</td></tr>\n<tr><td>Stone</td><td>17</td></tr>\n<tr><td>Iron, steel</td><td>19</td></tr>\n<tr><td>Mithral</td><td>21</td></tr>\n<tr><td>Adamantine</td><td>23</td></tr>\n</tbody></table>\n<h5>Object Hit Points</h5>\n<table class=\"humanoid-grid\"><thead><tr><th>Size</th><th>Fragile</th><th>Resilient</th></tr></thead><tbody>\n<tr><td>Tiny (bottle, lock)</td><td>2 (1d4)</td><td>5 (2d4)</td></tr>\n<tr><td>Small (chest, lute)</td><td>3 (1d6)</td><td>10 (3d6)</td></tr>\n<tr><td>Medium (barrel, chandelier)</td><td>4 (1d8)</td><td>18 (4d8)</td></tr>\n<tr><td>Large (cart, 10-ft. window)</td><td>5 (1d10)</td><td>27 (5d10)</td></tr>\n</tbody></table>\n<p><strong>Huge and Gargantuan Objects:</strong> normal weapons do little against most Huge and Gargantuan objects (a colossal statue, a towering column of stone), though a torch can burn a huge tapestry and an Earthquake spell can level a colossus. You can track Hit Points for such an object by dividing it into Large-or-smaller sections and tracking each separately — destroying one section (a Gargantuan statue's leg, say) could ruin the whole object — or you can simply decide how long it withstands whatever's acting against it.</p>\n<p><strong>Damage Threshold:</strong> large objects like castle walls often have extra resilience represented by a damage threshold. An object with a damage threshold is immune to all damage unless a single attack or effect deals damage equal to or greater than the threshold, in which case it takes the full amount; anything less is superficial and doesn't reduce its Hit Points.</p>\n<h5>Optional Rule: Doors</h5>\n<table class=\"humanoid-grid\"><thead><tr><th>Type</th><th>Thickness</th><th>Dmg. Threshold†</th><th>AC‡</th><th>HP</th></tr></thead><tbody>\n<tr><td>Wooden, Simple</td><td>1 in.</td><td>—</td><td>15</td><td>10</td></tr>\n<tr><td>Wooden, Good</td><td>2 in.</td><td>—</td><td>15</td><td>15</td></tr>\n<tr><td>Wooden, Heavy</td><td>4 in.</td><td>10</td><td>15</td><td>25</td></tr>\n<tr><td>Wooden, Reinforced</td><td>4 in.</td><td>15</td><td>17</td><td>40</td></tr>\n<tr><td>Stone</td><td>4 in.</td><td>25</td><td>17</td><td>60</td></tr>\n<tr><td>Iron</td><td>2 in.</td><td>30</td><td>19</td><td>100</td></tr>\n<tr><td>Portcullis, Wooden</td><td>3 in.</td><td>20</td><td>16</td><td>30</td></tr>\n<tr><td>Portcullis, Iron</td><td>2 in.</td><td>30</td><td>19</td><td>100</td></tr>\n<tr><td>Lock</td><td>—</td><td>5</td><td>19</td><td>30</td></tr>\n<tr><td>Hinge</td><td>—</td><td>5</td><td>19</td><td>30</td></tr>\n</tbody></table>\n<p>† An object with a damage threshold is immune to all damage from an attack or effect unless a single instance meets or exceeds the threshold, in which case it takes the full amount. These figures scale from the ship damage thresholds in the DMG (p. 119) — wooden ships range from 0 to 20, so stone doors were set at 25–30 and iron at 30.</p>\n<p>‡ AC values are based on the object-substance AC table above (DMG p. 246).</p>\n<h5>Optional Rule: Walls</h5>\n<table class=\"humanoid-grid\"><thead><tr><th>Type</th><th>Thickness</th><th>Dmg. Threshold†</th><th>AC‡</th><th>HP</th></tr></thead><tbody>\n<tr><td>Wood, Planks</td><td>6 in.</td><td>—</td><td>15</td><td>60</td></tr>\n<tr><td>Wood, Logs</td><td>1 ft.</td><td>—</td><td>15</td><td>70</td></tr>\n<tr><td>Masonry</td><td>1 ft.</td><td>25</td><td>17</td><td>90</td></tr>\n<tr><td>Masonry, Superior</td><td>1 ft.</td><td>25</td><td>17</td><td>100</td></tr>\n<tr><td>Masonry, Reinforced</td><td>1 ft.</td><td>30</td><td>18</td><td>180</td></tr>\n<tr><td>Hewn Stone</td><td>3 ft.</td><td>30</td><td>17</td><td>340</td></tr>\n<tr><td>Unworked Stone</td><td>5 ft.</td><td>30</td><td>17</td><td>600</td></tr>\n<tr><td>Iron</td><td>3 in.</td><td>30</td><td>19</td><td>200</td></tr>\n<tr><td>Magically Treated</td><td>—</td><td>+20</td><td>—</td><td>×2</td></tr>\n</tbody></table>"},
  {"id": "dropObscured", "title": "Obscured", "html": "<p><strong><a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-lightly-obscured\">Lightly Obscured</a></strong> = Disadvantage on <a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-wisdom\">Wisdom</a> (<a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-perception\">Perception</a>) <a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-ability-check\">checks</a> that rely on sight</p><p><strong><a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-heavily-obscured\">Heavily Obscured</a></strong> = You have the <a href=\"#\" class=\"gloss-ref\" data-ref=\"condition-blinded\">Blinded</a> condition while trying to see something in the area</p>"},
  {"id": "dropSellingMagicItems", "title": "Selling Magic Items", "html": "<p>These tables give base prices for magic items by rarity, and determine the offer once a buyer is found (e.g. \"the buyer offers half the price\").</p>\n<h5>Selling by Rarity</h5>\n<table class=\"humanoid-grid\"><thead><tr><th>Rarity</th><th>Base Price</th><th>Days to Find Buyer</th><th>d100 Roll Modifier*</th></tr></thead><tbody>\n<tr><td>Common</td><td>100 gp</td><td>1d4</td><td>+10</td></tr>\n<tr><td>Uncommon</td><td>500 gp</td><td>1d6</td><td>+0</td></tr>\n<tr><td>Rare</td><td>5,000 gp</td><td>1d8</td><td>—</td></tr>\n<tr><td>Very Rare</td><td>50,000 gp</td><td>1d10</td><td>-20</td></tr>\n</tbody></table>\n<p>* Apply this modifier to rolls on the Buyer's Offer table below.</p>\n<h5>Buyer's Offer</h5>\n<table class=\"humanoid-grid\"><thead><tr><th>d100 + Mod</th><th>You Find...</th></tr></thead><tbody>\n<tr><td>01-20</td><td>A buyer offering a tenth of the base price</td></tr>\n<tr><td>21-40</td><td>A buyer offering a quarter of the base price, and a shady buyer offering half the base price</td></tr>\n<tr><td>41-80</td><td>A buyer offering half the base price, and a shady buyer offering the full base price</td></tr>\n<tr><td>81-90</td><td>A buyer offering the full base price</td></tr>\n<tr><td>91-00</td><td>A shady buyer offering one and a half times the base price, no questions asked</td></tr>\n</tbody></table>"},
  {"id": "dropSkills", "title": "Skills by Ability", "html": "<p><strong class=\"skill-label-large\"><a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-strength\">Strength</a>:</strong> <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"glossary-athletics\">Athletics</a></p><p><strong class=\"skill-label-large\"><a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-dexterity\">Dexterity</a>:</strong> <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"glossary-acrobatics\">Acrobatics</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"glossary-sleight-of-hand\">Sleight of Hand</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"glossary-stealth\">Stealth</a></p><p><strong class=\"skill-label-large\"><a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-intelligence\">Intelligence</a>:</strong> <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"glossary-arcana\">Arcana</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"glossary-history\">History</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"glossary-investigation\">Investigation</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"glossary-nature\">Nature</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"glossary-religion\">Religion</a></p><p><strong class=\"skill-label-large\"><a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-wisdom\">Wisdom</a>:</strong> <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"glossary-animal-handling\">Animal Handling</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"glossary-insight\">Insight</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"glossary-medicine\">Medicine</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"glossary-perception\">Perception</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"glossary-survival\">Survival</a></p><p><strong class=\"skill-label-large\"><a href=\"#\" class=\"gloss-ref\" data-ref=\"glossary-charisma\">Charisma</a>:</strong> <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"glossary-deception\">Deception</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"glossary-intimidation\">Intimidation</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"glossary-performance\">Performance</a>, <a href=\"#\" class=\"gloss-ref skill-italic\" data-ref=\"glossary-persuasion\">Persuasion</a></p>"},
  {"id": "dropTrackingForaging", "title": "Tracking & Foraging", "html": "<p>Tracking and foraging are both Wisdom (Survival) checks, with a DC based on the circumstances shown below.</p>\n<h5>Foraging – Food &amp; Water</h5>\n<table class=\"humanoid-grid\"><thead><tr><th>Availability</th><th>Survival DC</th></tr></thead><tbody>\n<tr><td>Abundant food and water</td><td>10</td></tr>\n<tr><td>Limited food and water sources</td><td>15</td></tr>\n<tr><td>Very little, if any, food or water</td><td>20</td></tr>\n</tbody></table>\n<h5>Foraging – Ingredients</h5>\n<table class=\"humanoid-grid\"><thead><tr><th>Method of Search</th><th>Survival DC</th></tr></thead><tbody>\n<tr><td>Dedicated search without traveling</td><td>10</td></tr>\n<tr><td>Traveling at a slow or stealthy pace</td><td>15</td></tr>\n<tr><td>Traveling at a normal pace</td><td>18</td></tr>\n<tr><td>Traveling at a fast pace</td><td>21</td></tr>\n</tbody></table>\n<h5>Tracking</h5>\n<table class=\"humanoid-grid\"><thead><tr><th>Ground Surface</th><th>Survival DC</th></tr></thead><tbody>\n<tr><td>Soft surface, such as snow or sand</td><td>10</td></tr>\n<tr><td>Dirt or grass</td><td>15</td></tr>\n<tr><td>Bare stone</td><td>20</td></tr>\n<tr><td>Each day since the creature passed</td><td>+5</td></tr>\n<tr><td>Creature left an obvious trail (e.g. blood)</td><td>-5</td></tr>\n</tbody></table>"},
  {"id": "dropTravelPace", "title": "Travel and Pace", "html": "<p>Other penalties may reduce these further if the party is swimming, climbing, crawling, or crossing Difficult Terrain (see Pace Modifiers below).</p>\n<h5>Travel Pace</h5>\n<table class=\"humanoid-grid\"><thead><tr><th>Pace</th><th>Per Minute</th><th>Per Hour</th><th>Per Day</th></tr></thead><tbody>\n<tr><td>Fast</td><td>400 ft.</td><td>4 miles</td><td>30 miles</td></tr>\n<tr><td>Normal</td><td>300 ft.</td><td>3 miles</td><td>24 miles</td></tr>\n<tr><td>Slow</td><td>200 ft.</td><td>2 miles</td><td>18 miles</td></tr>\n</tbody></table>\n<table class=\"humanoid-grid\" style=\"margin-top:8px;\"><thead><tr><th>Draft Horse (40 ft. Speed)</th><th>Per Minute</th><th>Per Hour</th><th>Per Day</th></tr></thead><tbody>\n<tr><td>Fast</td><td>500 ft.</td><td>5 miles</td><td>40 miles</td></tr>\n<tr><td>Normal</td><td>400 ft.</td><td>4 miles</td><td>32 miles</td></tr>\n<tr><td>Slow</td><td>300 ft.</td><td>3 miles</td><td>24 miles</td></tr>\n</tbody></table>\n<table class=\"humanoid-grid\" style=\"margin-top:8px;\"><thead><tr><th>Riding/War Horse (60 ft. Speed)</th><th>Per Minute</th><th>Per Hour</th><th>Per Day</th></tr></thead><tbody>\n<tr><td>Fast</td><td>800 ft.</td><td>8 miles</td><td>64 miles</td></tr>\n<tr><td>Normal</td><td>600 ft.</td><td>6 miles</td><td>48 miles</td></tr>\n<tr><td>Slow</td><td>400 ft.</td><td>4 miles</td><td>32 miles</td></tr>\n</tbody></table>\n<h5>Travel by Map Scale</h5>\n<table class=\"humanoid-grid\"><thead><tr><th>Map Scale</th><th>Slow Pace</th><th>Normal Pace</th><th>Fast Pace</th></tr></thead><tbody>\n<tr><td>Dungeon (1 sq. = 10 ft.)</td><td>20 sq./min.</td><td>30 sq./min.</td><td>40 sq./min.</td></tr>\n<tr><td>City (1 sq. = 100 ft.)</td><td>2 sq./min.</td><td>3 sq./min.</td><td>4 sq./min.</td></tr>\n<tr><td>Province (1 hex = 1 mi.)</td><td>2 hexes/hr., 18 hexes/day</td><td>3 hexes/hr., 24 hexes/day</td><td>4 hexes/hr., 30 hexes/day</td></tr>\n<tr><td>Kingdom (1 hex = 6 mi.)</td><td>1 hex/3 hr., 3 hexes/day</td><td>1 hex/2 hr., 4 hexes/day</td><td>1 hex/1½ hr., 5 hexes/day</td></tr>\n</tbody></table>\n<table class=\"humanoid-grid\" style=\"margin-top:8px;\"><thead><tr><th>Draft Horse (40 ft. Speed)</th><th>Slow Pace</th><th>Normal Pace</th><th>Fast Pace</th></tr></thead><tbody>\n<tr><td>City (1 sq. = 100 ft.)</td><td>3 sq./min.</td><td>4 sq./min.</td><td>5 sq./min.</td></tr>\n<tr><td>Province (1 hex = 1 mi.)</td><td>3 hexes/hr., 24 hexes/day</td><td>4 hexes/hr., 32 hexes/day</td><td>5 hexes/hr., 40 hexes/day</td></tr>\n<tr><td>Kingdom (1 hex = 6 mi.)</td><td>1 hex/2 hr., 4 hexes/day</td><td>1 hex/1½ hr., 5 hexes/day</td><td>1 hex/1 hr., 7 hexes/day</td></tr>\n</tbody></table>\n<table class=\"humanoid-grid\" style=\"margin-top:8px;\"><thead><tr><th>Riding/War Horse (60 ft. Speed)</th><th>Slow Pace</th><th>Normal Pace</th><th>Fast Pace</th></tr></thead><tbody>\n<tr><td>City (1 sq. = 100 ft.)</td><td>4 sq./min.</td><td>6 sq./min.</td><td>8 sq./min.</td></tr>\n<tr><td>Province (1 hex = 1 mi.)</td><td>4 hexes/hr., 36 hexes/day</td><td>6 hexes/hr., 48 hexes/day</td><td>8 hexes/hr., 60 hexes/day</td></tr>\n<tr><td>Kingdom (1 hex = 6 mi.)</td><td>2 hexes/3 hr., 6 hexes/day</td><td>1 hex/1 hr., 8 hexes/day</td><td>4 hexes/3 hr., 10 hexes/day</td></tr>\n</tbody></table>\n<h5>Pace Modifiers</h5>\n<table class=\"humanoid-grid\"><thead><tr><th>Movement</th><th>Speed</th></tr></thead><tbody>\n<tr><td>Difficult Terrain</td><td>Half speed</td></tr>\n<tr><td>Climbing</td><td>Half speed (quarter in Difficult Terrain)</td></tr>\n<tr><td>Swimming</td><td>Half speed (quarter in Difficult Terrain)</td></tr>\n<tr><td>Crawling</td><td>Half speed (quarter in Difficult Terrain)</td></tr>\n</tbody></table>\n<p>Climbing, swimming, and crawling may also require a Strength (Athletics) or Dexterity (Acrobatics) check, at the DM's discretion.</p>\n<p><strong>Forced March:</strong> traveling more than 8 hours in a day risks Exhaustion. Each character must make a Constitution saving throw at the end of every additional hour, DC 10 + 1 per hour past 8. On a failed save, the character suffers one level of Exhaustion.</p>\n<p><strong>Mounts:</strong> can double their travel distance for one hour (or more, if fresh mounts are available roughly every 10 miles).</p>\n<p><strong>Vehicles:</strong> wagons and carriages move at normal pace. Waterborne vessels use their own speed and aren't subject to pace penalties or bonuses — depending on the vessel and crew, a ship may be able to travel 24 hours a day.</p>\n<p><strong>Activities While Traveling:</strong> a character actively navigating, mapping, tracking, or foraging while traveling doesn't benefit from a Passive Perception check during that time.</p>"},
  {"id": "dropVisionAbilities", "title": "Vision Abilities", "html": "<table class=\"humanoid-grid\"><thead><tr><th>Ability</th><th>Effect</th><th>Source</th></tr></thead><tbody>\n<tr><td>Blindsight</td><td>Perceive your surroundings without relying on sight</td><td>PHB p. 183</td></tr>\n<tr><td>Darkvision</td><td>See in darkness as if it were dim light; can't discern color in darkness</td><td>PHB p. 183</td></tr>\n<tr><td>Darkvision (spell)</td><td>2nd-level spell; a touched, willing creature gains 60 ft. Darkvision for 8 hours</td><td>PHB p. 230</td></tr>\n<tr><td>Races with 60 ft. Darkvision</td><td>Dwarf, Elf, Gnome, Half-Elf, Half-Orc, Tiefling</td><td></td></tr>\n<tr><td>Exotic Races with 60 ft. Darkvision</td><td>Aasimar, Bugbear, Feral Tiefling, Firbolg, Kobold, Leonin, Orc (Exandria), Orc (Eberron), Shifter, Simic Hybrid</td><td></td></tr>\n<tr><td>Truesight</td><td>See in darkness, see Invisible creatures, see through visual illusions, see a shapechanger's true form, and see into the Ethereal Plane</td><td>PHB p. 185</td></tr>\n<tr><td>True Seeing (spell)</td><td>6th-level spell; a touched, willing creature gains Truesight out to 120 ft.</td><td>PHB p. 284</td></tr>\n</tbody></table>"},
  {"id": "dropVisionLightSources", "title": "Vision - Light Sources", "html": "<table class=\"humanoid-grid\"><thead><tr><th>Mundane Source</th><th>Bright Light</th><th>Dim Light</th><th>Duration</th></tr></thead><tbody>\n<tr><td>Candle</td><td>5 ft.</td><td>+5 ft.</td><td>6 hours</td></tr>\n<tr><td>Lamp</td><td>15 ft.</td><td>+30 ft.</td><td>6 hours</td></tr>\n<tr><td>Lantern, Bullseye</td><td>60 ft. cone</td><td>+60 ft.</td><td>6 hours</td></tr>\n<tr><td>Lantern, Hooded</td><td>30 ft.</td><td>+30 ft.</td><td>6 hours</td></tr>\n<tr><td>Lowered Hood</td><td>—</td><td>+5 ft.</td><td>—</td></tr>\n<tr><td>Torch</td><td>20 ft.</td><td>+20 ft.</td><td>1 hour</td></tr>\n</tbody></table>\n<table class=\"humanoid-grid\" style=\"margin-top:8px;\"><thead><tr><th>Magic Source</th><th>Bright Light</th><th>Dim Light</th><th>Duration</th></tr></thead><tbody>\n<tr><td>Continual Flame</td><td>20 ft.</td><td>+20 ft.</td><td>Until dispelled</td></tr>\n<tr><td>Dancing Lights</td><td>—</td><td>10 ft.</td><td>1 minute</td></tr>\n<tr><td>Faerie Fire</td><td>—</td><td>10 ft.</td><td>1 minute</td></tr>\n<tr><td>Flame Blade</td><td>10 ft.</td><td>+10 ft.</td><td>10 minutes</td></tr>\n<tr><td>Flaming Sphere</td><td>20 ft.</td><td>+20 ft.</td><td>1 minute</td></tr>\n<tr><td>Holy Aura</td><td>—</td><td>5 ft.</td><td>1 minute</td></tr>\n<tr><td>Light</td><td>20 ft.</td><td>+20 ft.</td><td>1 hour</td></tr>\n<tr><td>Moonbeam</td><td>—</td><td>5 ft. cylinder</td><td>1 minute</td></tr>\n<tr><td>Prismatic Wall</td><td>100 ft.</td><td>+100 ft.</td><td>10 minutes</td></tr>\n<tr><td>Wall of Fire</td><td>60 ft.</td><td>+60 ft.</td><td>1 minute</td></tr>\n</tbody></table>"},
  {"id": "dropWildernessNavigation", "title": "Wilderness Navigation", "html": "<p>Navigating unfamiliar wilderness can be difficult, and a party may end up heading the wrong way. A DM may call for a Wisdom (Survival) check to see if the party stays on course, using the table below to set the DC.</p>\n<table class=\"humanoid-grid\"><thead><tr><th>Terrain</th><th>DC</th></tr></thead><tbody>\n<tr><td>Forest, jungle, swamp, mountains, or open sea with overcast skies and no land in sight</td><td>15</td></tr>\n<tr><td>Arctic, desert, hills, or open sea with clear skies and no land in sight</td><td>10</td></tr>\n<tr><td>Grassland, meadow, or farmland</td><td>5</td></tr>\n</tbody></table>"}
]};
